tool_calls.arguments_from_deltas:
{"command": "$m = @(@(1,1000,700),@(2,2000,1400),@(3,3000,2100),@(4,4000,1400),@(5,5000,3500),@(6,6000,4200));
$rev=0; $cost=0; foreach($r in $m){$rev+=$r[1]; $cost+=$r[2]}
$profit=$rev-$cost; $margin=[math]::Round(($profit/$rev)*100,2)
"TOTAL=$rev COST=$cost PROFIT=$profit MARGIN=$margin%"
$m | ForEach-Object { "M{0}: REV={1} COST={2} PROFIT={3}" -f $_[0],$_[1],$_[2],($_[1]-$_[2]) }", "description": "在内存中计算逐月与汇总经营数据"}

